const lv_image_dsc_t *ui_weather_icon(int code, bool large)
{
    unsigned lo = 0, hi = sizeof(entries) / sizeof(entries[0]);
    while (lo < hi)
    {
        unsigned mid = lo + (hi - lo) / 2;
        if (entries[mid].code == code) return large ? entries[mid].large : entries[mid].small;
        if (entries[mid].code < code) lo = mid + 1;
        else hi = mid;
    }
    return large ? &w999_160 : &w999_48;
}
